"""Gera vitrine GitHub Pages a partir das respostas reais do motor local.
As decisões são snapshots, não execução do Python no browser.
"""
import json
import html
from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from resolveai.core import triage

root=Path(__file__).resolve().parents[1]
records=[json.loads(x) for x in (root/'data/tickets_labeled.jsonl').read_text(encoding='utf8').splitlines() if x.strip()]
content=[]
for row in records:
    result=triage(row['ticket_id'],row['text'])
    content.append({'ticket_id':row['ticket_id'],'text':row['text'],'category':result['category'],'priority':result['priority'],'team':result['team'],'review':result['requires_human_review'],'explanation':result['reason_code'],'reply':result['suggested_reply_draft'],'guidance':result['policy_reference']['guidance'],'evidence':result['evidence']})
encoded=json.dumps(content,ensure_ascii=False).replace('<','\\u003c')
report=json.loads((root/'reports/evaluation.json').read_text(encoding='utf8'))
rate=f"{report['category_accuracy']*100:.0f}%"
content_html=r'''<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ResolveAI — Explorador de triagem</title><style>
:root{font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;background:#101820;color:#eaf1f4;color-scheme:dark}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1220px;margin:0 auto;padding:38px 24px 60px}.eyebrow{font-size:11px;font-weight:700;letter-spacing:2px;color:#8cd7bd}.top{display:flex;align-items:center;justify-content:space-between;gap:16px}.top small{font-size:12px;color:#a4b6c2}.title{font-size:clamp(36px,5vw,65px);letter-spacing:-2px;line-height:1.04;margin:32px 0 12px}.sub{line-height:1.65;color:#b2c0ca;max-width:760px;margin:0 0 25px;font-size:15px}.notice{background:#29333b;border:1px solid #45535b;border-radius:10px;padding:14px 18px;font-size:13px;color:#e3ebf1;line-height:1.5;margin:20px 0 28px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:24px 0 30px}.metric{background:#17232d;border:1px solid #30414c;border-radius:13px;padding:18px}.metric strong{display:block;font-size:30px;font-weight:720;letter-spacing:-1px}.metric small{color:#a7b8c4}.main{display:grid;grid-template-columns:0.92fr 1.08fr;gap:16px}.panel{background:#17232d;border:1px solid #30414c;border-radius:14px;padding:22px;min-width:0}.panel h2{margin:0 0 8px;font-size:17px;letter-spacing:-.2px}.hint{color:#9db0bd;font-size:12px;line-height:1.6}.filters{display:flex;gap:7px;flex-wrap:wrap;margin:15px 0}.btn{background:#1c3039;border:1px solid #405361;color:#cbd9e2;padding:8px 11px;border-radius:7px;cursor:pointer;font-size:12px}.btn[aria-pressed=true],.btn:hover{border-color:#79cfb4;background:#254337;color:#e6fff6}.cases{height:470px;overflow-y:auto;display:grid;gap:7px;align-content:start;padding-right:4px}.ticket{background:#111c24;border:1px solid #2c3e49;color:#e9eef2;padding:13px;border-radius:9px;cursor:pointer;text-align:left;line-height:1.45;font-size:13px}.ticket.active{border-color:#75cbb1;background:#203d39}.ticket b{font-size:11px;color:#91c6bd;display:block;margin-bottom:5px}.output{border:1px solid #40525c;border-radius:11px;background:#101e27;padding:16px;margin-top:15px;min-height:365px}.tags{display:flex;gap:8px;flex-wrap:wrap;margin:13px 0 15px}.tag{padding:6px 9px;border-radius:7px;font-size:11px;font-weight:700;background:#274039;color:#bef2d7}.tag.high{background:#593c38;color:#ffb9ad}.tag.critical{background:#612a33;color:#ffd3d7}.kv{font-size:13px;color:#bdcbd3;margin-bottom:13px}.kv b{color:#f0f6f9}.reply{padding:12px;background:#24333c;border-left:3px solid #82ceb8;border-radius:4px;font-size:13px;line-height:1.6;color:#e1eaef;margin:13px 0}.foot{color:#93a8b6;font-size:12px;line-height:1.6;margin-top:25px}a{color:#9bdcce}.empty{color:#8fa4b1;padding:14px}.stack{display:flex;align-items:center;gap:8px;font-size:11px;color:#a6b7c3;flex-wrap:wrap}.dot{border:1px solid #43695f;background:#243b36;border-radius:20px;padding:5px 9px}#detail-note{color:#cbdbe5;line-height:1.5;font-size:14px}@media(max-width:820px){.main{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr 1fr}.cases{height:290px}.wrap{padding:22px 16px}.top{flex-wrap:wrap}}@media(max-width:500px){.metrics{grid-template-columns:1fr 1fr}.metric strong{font-size:24px}}</style></head>
<body><main class="wrap"><div class="top"><span class="eyebrow">RESOLVEAI / AI BUILDER PORTFOLIO</span><small>PROTÓTIPO INDEPENDENTE · 2026</small></div><h1 class="title">Reclamações entram.<br>Prioridades ficam claras.</h1><p class="sub">Explorador de decisões pré-calculadas por uma API de triagem em Python: categoria, prioridade, revisão humana e justificativa. Construído para demonstrar um fluxo de negócio com guardrails, testes e métricas verificáveis.</p><div class="notice"><b>Demonstração offline de snapshots.</b> Esta página mostra resultados gerados pelo motor local; não consulta uma API ao vivo, não usa dados de clientes e não está ligada ao iFood. Políticas e SLAs são fictícios.</div><section class="metrics"><div class="metric"><strong>42</strong><small>tickets sintéticos rotulados</small></div><div class="metric"><strong>27</strong><small>testes automatizados locais</small></div><div class="metric"><strong>__ACCURACY__</strong><small>acurácia no conjunto preparado* </small></div></section><div class="main"><section class="panel"><h2>Exemplos de tickets</h2><div class="hint">Selecione uma categoria e clique no ticket para inspecionar a decisão.</div><div class="filters" id="filters"></div><div class="cases" id="cases"></div></section><section class="panel"><h2>Triagem auditável</h2><div class="hint">Saída gerada pelo mecanismo de regras e políticas fictícias.</div><div class="output"><div class="eyebrow" id="ticket-id"></div><h3 id="ticket-text" style="font-size:20px;line-height:1.4;margin:9px 0 12px"></h3><div class="tags" id="tags"></div><div class="kv"><b>Equipe:</b> <span id="team"></span></div><div class="kv"><b>Motivo da decisão:</b> <span id="reason"></span></div><div class="kv"><b>Política da demonstração:</b> <span id="guidance"></span></div><div class="reply"><b>Rascunho (não enviado):</b><div id="reply"></div></div><div class="hint">Etapas de execução:</div><div class="stack"><span class="dot">Classificação</span><span>→</span><span class="dot">Consulta de política</span><span>→</span><span class="dot">Guardrails</span><span>→</span><span class="dot">Roteamento</span></div></div></section></div><p class="foot">*As métricas foram calculadas localmente sobre casos fictícios e curados para o MVP; não medem generalização, performance de LLM nem ganhos reais de produtividade. O repositório contém a API, o código da avaliação, os testes e fluxos n8n validado localmente: 4 tickets e 3 revisões humanas por execução. Esta página exibe somente snapshots.</p></main><script>
const DATA = __DATA__;
let selected='todos'; let activeId='';
const labels={'todos':'Todos','entrega_atrasada':'Entrega','reembolso':'Reembolso','cobranca':'Cobrança','qualidade_alimento':'Qualidade','acesso_conta':'Conta','outros':'Outros'};
const filters=document.getElementById('filters');const cases=document.getElementById('cases');
function make(tag,txt,cl){const el=document.createElement(tag);if(txt!==undefined)el.textContent=txt;if(cl)el.className=cl;return el}
function renderFilters(){filters.replaceChildren();Object.entries(labels).forEach(([key,name])=>{let b=make('button',name,'btn');b.setAttribute('aria-pressed',String(selected===key));b.onclick=()=>{selected=key;renderFilters();renderCases()};filters.append(b)})}
function renderCases(){cases.replaceChildren();const xs=DATA.filter(x=>selected==='todos'||x.category===selected);xs.forEach(x=>{let b=make('button',undefined,'ticket'+(x.ticket_id===activeId?' active':''));b.append(make('b',x.ticket_id+' · '+labels[x.category]));b.append(make('span',x.text));b.onclick=()=>choose(x.ticket_id);cases.append(b)})}
function choose(id){activeId=id;const x=DATA.find(t=>t.ticket_id===id);document.getElementById('ticket-id').textContent=x.ticket_id;document.getElementById('ticket-text').textContent=x.text;document.getElementById('team').textContent=x.team;document.getElementById('reason').textContent=x.explanation;document.getElementById('guidance').textContent=x.guidance;document.getElementById('reply').textContent=x.reply;let tags=document.getElementById('tags');tags.replaceChildren();tags.append(make('span',labels[x.category],'tag'));tags.append(make('span','Prioridade: '+x.priority,'tag '+(x.priority==='critica'?'critical':x.priority==='alta'?'high':'')));tags.append(make('span',x.review?'Revisão humana: SIM':'Revisão humana: NÃO','tag'));renderCases()}
renderFilters();choose('SYN025');
</script></body></html>'''
content_html=content_html.replace('__ACCURACY__',rate).replace('__DATA__',encoded)
(root/'index.html').write_text(content_html,encoding='utf8')
print('Created index.html',len(content_html), 'bytes')
